import { Component } from '@angular/core';

@Component({
  standalone: true,
  template: `
    <section>
      <h1 class="hlm-h1">Introduction</h1>
      <p class="hlm-lead">Accessible UI primitives for Angular. Install the behavior. Copy the styles.</p>

      <p class="hlm-p">
        <code>spartan/ui</code> gives you accessible, customizable components for Angular applications. Built with signals, SSR compatible, and zoneless ready - no full-stack setup required, just add to any Angular project.
      </p>

      <h2 class="hlm-h2">How it works</h2>
      <p class="hlm-p">spartan uses a two-layer architecture that gives you both maintained accessibility and complete style ownership:</p>

      <div class="info-grid">
        <div class="info-card">
          <h3 class="hlm-h3">🧠 spartan/ui/brain</h3>
          <p class="hlm-p">Unstyled, accessible primitives installed via npm. Handles ARIA attributes, keyboard navigation, and focus management.</p>
          <span class="hlm-small">You install it: Regular dependency with updates and maintenance included.</span>
        </div>
        <div class="info-card">
          <h3 class="hlm-h3">⚡ spartan/ui/helm l la</h3>
          <p class="hlm-p">Styled components with a shadcn-inspired design system. Built with Tailwind CSS classes you can edit directly.</p>
          <span class="hlm-small">You copy it: Lives in your codebase. Customize without fighting a theming API.</span>
        </div>
      </div>

      <h2 class="hlm-h2">FAQ</h2>
      <div class="faq-section">
        <h3 class="hlm-h3">What is spartan/ui?</h3>
        <p class="hlm-p">A collection of accessible UI primitives for Angular. You install behavior via npm and copy styles into your codebase for complete customization.</p>

        <h3 class="hlm-h3">Do I need AnalogJs or a full-stack setup?</h3>
        <p class="hlm-p">No. spartan/ui works with any Angular application. The spartan/stack is optional for full-stack development.</p>
      </div>
    </section>
  `,
